  "q": "栽培漁業や養殖について述べた文として正しいものを次から選んで、記号で答えなさい。ア栽培漁業では、たまごからかえした後、海や川などに放して自然の中で大きく育ててからとる　イ栽培漁業も養殖も海岸で行われていて、川や湖では行われていない　ウたまごからかえした量と後でとれた量とをくらべると、栽培漁業のほうが養殖よりも大きな割合で収穫できる　エ魚は新鮮さが重要なので、栽培漁業も養殖も、その多くは大都市の近くで行われている",
